#include <iostream>
#include <string>

using namespace std;

int main() {
    int n;
    string s;
    cin >> n >> s;

    string ans;

    for (size_t i = 0; i < s.size();) {
        if (i + 2 < s.size() && s.compare(i, 3, "ogo") == 0) {
            ans += "***";
            i += 3;

            while (i + 1 < s.size() && s.compare(i, 2, "go") == 0) {
                i += 2;
            }
        } else {
            ans += s[i++];
        }
    }

    cout << ans;
    return 0;
}

